    const all=points.concat(curve),minX=Math.min(0,...all.map(p=>p[0])),maxX=Math.max(...all.map(p=>p[0])),minY=Math.min(0,...all.map(p=>p[1])),maxY=Math.max(...all.map(p=>p[1]));const dx=maxX-minX||1,dy=maxY-minY||1,x0=minX,x1=maxX+dx*.05,y0=minY-(minY<0?dy*.06:0),y1=maxY+dy*.12,x=v=>L+(v-x0)/(x1-x0)*(W-L-R),y=v=>H-B-(v-y0)/(y1-y0)*(H-T-B);
